function portrait(p,big){const g='g'+p.id;return `<svg viewBox="0 0 200 200" aria-hidden="true"><defs><linearGradient id="${g}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${p.shirt}"/><stop offset="1" stop-color="color-mix(in srgb,${p.shirt} 60%,#000)"/></linearGradient></defs>
${p.hs==='long'?`<path d="M58 92c-4-40 18-60 42-60s48 18 42 62c4 30-4 52-10 62H68c-8-12-14-34-10-64z" fill="${p.hair}"/>`:''}
<path d="M26 206c4-40 36-62 74-62s70 22 74 62z" fill="${p.shirt}"/><path d="M26 206c4-40 36-62 74-62s70 22 74 62z" fill="url(#${g})" opacity=".55"/>
<rect x="86" y="112" width="28" height="38" rx="13" fill="${p.skin}"/><rect x="86" y="118" width="28" height="12" fill="#000" opacity=".08"/>
<ellipse cx="100" cy="88" rx="33" ry="39" fill="${p.skin}"/>
${p.hs==='long'?`<path d="M67 86c0-30 16-46 34-46s33 16 33 44c-10-14-22-22-36-20-12 2-22 10-31 22z" fill="${p.hair}"/>`:`<path d="M66 84c0-30 16-45 35-45 20 0 34 14 34 42-6-12-18-19-34-19s-27 8-35 22z" fill="${p.hair}"/>`}
<circle cx="88" cy="92" r="3.4" fill="#231F1A"/><circle cx="112" cy="92" r="3.4" fill="#231F1A"/><path d="M90 108q10 8 20 0" stroke="#231F1A" stroke-width="3" fill="none" stroke-linecap="round"/>
<ellipse cx="80" cy="102" rx="6" ry="3.5" fill="#FF7A6B" opacity=".25"/><ellipse cx="120" cy="102" rx="6" ry="3.5" fill="#FF7A6B" opacity=".25"/>
<path d="M82 148l18 15 18-15" stroke="#fff" stroke-width="3" fill="none" opacity=".45" stroke-linecap="round"/></svg>`}
const evTag=t=>t==='v'?`<span class="pill blue" style="height:22px;font-size:11.5px">${ic('check',12,'',2.6)}Validated</span>`:`<span class="pill warn" style="height:22px;font-size:11.5px">${ic('alert',12)}Assumption</span>`;
function avatarPage(p,back,ctx=''){const S=(i,t,ic_,list,cls='')=>`<section class="sp" style="--i:${i};--c:${p.c}"><h3>${ic(ic_,16)}${t}</h3>${list}</section>`;const ul=a=>`<ul>${a.map(x=>`<li>${x}</li>`).join('')}</ul>`;
return `<div class="toolbar"><button class="btn quiet sm" data-act="nav:${back}">${ic('right',16).replace('<svg','<svg style="transform:scaleX(-1)"')}All avatars</button><span class="grow"></span><span class="pill">${p.v} · reviewed ${p.rev} by ${PEOPLE[p.by][0].split(' ')[0]}</span><button class="btn ghost sm" data-act="toast:Version history opens here.">${ic('hist',16)}<span class="hide-m">History</span></button><button class="btn ink sm" data-act="toast:Edit mode: every section becomes editable, with Save and Cancel.">${ic('edit',16)}Edit</button></div>${ctx}
<div class="ava"><div class="specs left">${S(0,'Who they are','user',`<div class="stat3" style="margin-bottom:10px">${p.stats.map(([b,s])=>`<div><b>${b}</b><small>${s}</small></div>`).join('')}</div>${ul(p.who)}`)}${S(1,'Goals','target',ul(p.goals))}${S(2,'Pains','alert',ul(p.pains))}</div>
<div class="ava-center"><div class="portrait" style="--c:${p.c}">${portrait(p)}<span class="ring"></span><span class="badge">${p.role}</span></div><h1>${p.n.split(',')[0]}</h1><p class="over">${p.n.split(', ')[1]||''}</p><q>${p.q}</q><div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center">${p.used.map(u=>`<span class="tag">${ic('funnels',12)} ${u}</span>`).join('')}</div></div>
<div class="specs right">${S(3,'Motivations','heart',ul(p.mot))}${S(4,'Objections','xcircle',ul(p.obj))}${S(5,'Language they use','msg',`<div style="display:grid;gap:8px">${p.lang.map(l=>`<span class="quote">“${l}”</span>`).join('')}</div>`)}${S(6,'Buying triggers','flag',ul(p.trig))}</div></div>
<div class="grid3" style="margin-top:24px"><section class="panel" style="padding:18px 20px"><p class="sec-t" style="margin-top:0">${ic('shield',16)}Evidence</p><div style="display:grid;gap:10px">${p.ev.map(([e,t])=>`<div style="display:flex;justify-content:space-between;gap:10px;align-items:center;font-size:14px">${e}${evTag(t)}</div>`).join('')}</div></section>
<section class="panel" style="padding:18px 20px;background:var(--sunk);box-shadow:none"><p class="sec-t" style="margin-top:0">${ic('lock',16)}Internal notes · never shared</p><p class="tx2" style="font-size:14px">Clara responds best to proof from other mums. Avoid “hustle” language.</p></section>
<section class="panel" style="padding:18px 20px"><p class="sec-t" style="margin-top:0">${ic('share',16)}Shared with clients</p><p class="tx2" style="font-size:14px">Not shared. Sharing never includes internal notes, and the Client Portal is locked.</p></section></div>`}
